-- #823. Filename generated by Supabase CLI 2.118.0, run 38893710541.
-- Preserve original references and historical rows. Conflicts abort the migration;
-- never silently delete, merge or renumber accounting evidence.
begin;

alter table public.supplier_invoices
  add column invoice_reference_key text generated always as
    (upper(regexp_replace(normalize(btrim(supplier_invoice_number), NFKC), '[[:space:]]+', '', 'g'))) stored;

-- Create replacements BEFORE dropping the old constraint. Unique indexes also
-- arbitrate concurrent inserts; a browser-only lookup cannot do that.
create unique index supplier_invoices_supplier_reference_uidx
  on public.supplier_invoices(company_id, supplier_id, invoice_reference_key);
create unique index supplier_invoices_original_uidx
  on public.supplier_invoices(company_id, lower(pdf_sha256))
  where pdf_sha256 is not null;

alter table public.supplier_invoices
  add constraint supplier_invoice_reference_not_empty
    check (char_length(invoice_reference_key) between 1 and 100
      and supplier_invoice_number !~ '[[:cntrl:]]') not valid;
alter table public.supplier_invoices validate constraint supplier_invoice_reference_not_empty;
alter table public.supplier_invoices
  drop constraint supplier_invoices_company_id_supplier_invoice_number_key;

comment on column public.supplier_invoices.invoice_reference_key is
  'Duplicate-detection key only. Original reference remains unchanged. NFKC, uppercase and whitespace normalization; punctuation and leading zeros remain significant. Scope: company and registered supplier. Not proof of supplier identity or invoice authenticity.';

commit;
